def fitness_bmi_category(chromosome, target):
    weight = chromosome[0]
    height = chromosome[1]

    if height <= 0:
        distance = 0 if target == 'invalid_height' else 1
    else:
        bmi = weight / (height * height)

        if bmi < 18.5:
            distance = 0 if target == 'underweight' else max(0, 18.5 - bmi)
        elif bmi < 25:
            distance = 0 if target == 'normal' else max(0, min(bmi - 18.5, 25 - bmi))
        elif bmi < 30:
            distance = 0 if target == 'overweight' else max(0, min(bmi - 25, 30 - bmi))
        else:
            distance = 0 if target == 'obese' else max(0, bmi - 30)

    if target not in ['invalid_height', 'underweight', 'normal', 'overweight', 'obese']:
        raise ValueError('Unknown target')

    return distance

