def fitness_number_kind(chromosome, target):
    x = chromosome[0]
    if target == "zero":
        return max(0, abs(x))
    elif target == "even":
        if x == 0:
            return 1
        elif x % 2 == 0:
            return 0
        else:
            return 1
    elif target == "odd":
        if x == 0:
            return 1
        elif x % 2 != 0:
            return 0
        else:
            return 1
    else:
        raise ValueError("Unknown target")

