def fitness_string_category(chromosome, target):
    s = chromosome[0]
    if target == "empty":
        return max(0, len(s))
    elif target == "long_palindrome":
        distance = max(0, 4 - len(s)) if s == s[::-1] else max(0, 4 - len(s)) + 1
        return distance
    elif target == "short_palindrome":
        distance = max(0, len(s) - 3) if s == s[::-1] else max(0, len(s) - 3) + 1
        return distance
    elif target == "long_non_palindrome":
        distance = max(0, 6 - len(s)) if s != s[::-1] else max(0, 6 - len(s)) + 1
        return distance
    elif target == "other":
        if s == "":
            return 1
        elif s == s[::-1] and len(s) > 3:
            return 2
        elif s == s[::-1]:
            return 1
        elif len(s) > 5:
            return 1
        else:
            return 0
    else:
        raise ValueError("Unknown target")

