def fitness_username_category(chromosome, target):
    username = chromosome[0]
    if target == "empty":
        return max(0, len(username))
    if target == "too_short":
        if len(username) >= 5:
            return max(0, len(username) - 4)
        else:
            return 0
    if target == "starts_with_digit":
        if not username or not username[0].isdigit():
            return max(0, 1)
        else:
            return 0
    has_digit = any(ch.isdigit() for ch in username)
    has_upper = any(ch.isupper() for ch in username)
    has_special = any(not ch.isalnum() for ch in username)
    if target == "strong_username":
        if len(username) < 10:
            return max(0, 10 - len(username))
        elif not has_digit:
            return max(0, 1)
        elif not has_upper:
            return max(0, 1)
        elif not has_special:
            return max(0, 1)
        else:
            return 0
    if target == "medium_username":
        if not has_digit:
            return max(0, 1)
        elif not has_upper:
            return max(0, 1)
        elif len(username) >= 10 and has_digit and has_upper and has_special:
            return max(0, 1)
        elif username[0].isdigit():
            return max(0, 1)
        elif len(username) < 5:
            return max(0, 1)
        else:
            return 0
    if target == "weak_username":
        if has_digit and has_upper:
            return max(0, 1)
        elif len(username) >= 10 and has_digit and has_upper and has_special:
            return max(0, 1)
        elif username[0].isdigit():
            return max(0, 1)
        elif len(username) < 5:
            return max(0, 1)
        else:
            return 0
    raise ValueError("Unknown target")

